<span class="line" data-v-928702f0><span style="--shiki-dark:#72F088;--shiki-light:#005CC5;" data-v-928702f0>    &quot;url&quot;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;" data-v-928702f0>: </span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;" data-v-928702f0>&quot;https://registry.your-org.com&quot;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;" data-v-928702f0>,</span></span>
